/* ------------------------------------------------------------------ *
 * 2.4  Source badge
 * ------------------------------------------------------------------ */

const SOURCE_COLORS = {
  call: "bg-emerald-50 text-emerald-700 border border-emerald-200",
  email: "bg-blue-50 text-blue-700 border border-blue-200",
  "existing customer": "bg-violet-50 text-violet-700 border border-violet-200",
  partner: "bg-orange-50 text-orange-700 border border-orange-200",
  meta: "bg-orange-100 text-orange-700 border border-orange-200",
  "public relations": "bg-pink-50 text-pink-700 border border-pink-200",
  "web site": "bg-cyan-50 text-cyan-700 border border-cyan-200",
  campaign: "bg-amber-50 text-amber-700 border border-amber-200",
  other: "bg-slate-100 text-slate-700 border border-slate-200",
  acl: "bg-gradient-to-r from-fuchsia-50 to-violet-50 text-violet-700 border border-violet-200 shadow-sm",
};

const normalizeSource = (source) =>
  source?.trim()?.replace(/\s+/g, " ")?.toLowerCase();

export const getSourceColor = (source) =>
  SOURCE_COLORS[normalizeSource(source)] ||
  "bg-gray-100 text-gray-700 border border-gray-200";

/**
 * Label rule: show cSubSource if present; else if source is `acl` show
 * "Aajneeti"; else show source.
 */
export const getSourceLabel = (lead) => {
  if (lead?.cSubSource) return lead.cSubSource;
  if (normalizeSource(lead?.source) === "acl") return "Aajneeti";
  return lead?.source || "—";
};

/**
 * The hue a source badge should use. cSubSource drives the label but the
 * colour falls back to the raw source when the sub-source is unmapped.
 */
export const getSourceBadgeColor = (lead) => {
  const sub = normalizeSource(lead?.cSubSource);
  if (sub && SOURCE_COLORS[sub]) return SOURCE_COLORS[sub];
  return getSourceColor(lead?.source);
};

/* ------------------------------------------------------------------ *
 * 2.5  Avatar colours (deterministic, never random)
 * ------------------------------------------------------------------ */

export const ASSIGNEE_PALETTE = [
  "#6366F1",
  "#22C55E",
  "#F59E0B",
  "#EF4444",
  "#06B6D4",
  "#8B5CF6",
  "#EC4899",
  "#14B8A6",
];

/** A person's avatar colour must be identical everywhere they appear. */
export const getAvatarColor = (name) => {
  const value = String(name || "");
  let hash = 0;
  for (let i = 0; i < value.length; i += 1) {
    hash = (hash + value.charCodeAt(i)) >>> 0;
  }
  return ASSIGNEE_PALETTE[hash % ASSIGNEE_PALETTE.length];
};

/** Single word -> first letter; else first letter of first + first of LAST. */
export const getInitials = (name) => {
  const words = String(name || "").trim().split(/\s+/).filter(Boolean);
  if (!words.length) return "?";
  if (words.length === 1) return words[0][0].toUpperCase();
  return (words[0][0] + words[words.length - 1][0]).toUpperCase();
};

/* ------------------------------------------------------------------ *
 * 2.6  Follow-up / "next contact" tone
 * ------------------------------------------------------------------ */

const TONES = {
  rose: {
    tone: "rose",
    classes: "bg-rose-50 border-rose-200 text-rose-700",
    icon: "AlertCircle",
  },
  amber: {
    tone: "amber",
    classes: "bg-amber-50 border-amber-200 text-amber-800",
    icon: "Clock",
  },
  emerald: {
    tone: "emerald",
    classes: "bg-emerald-50 border-emerald-200 text-emerald-700",
    icon: "Calendar",
  },
  muted: {
    tone: "muted",
    classes: "bg-slate-50 border-slate-200 text-slate-500",
    icon: "CalendarOff",
  },
};

/**
 * Resolve the tone + human descriptor for a next-contact timestamp.
 * overdue -> rose, due today -> amber, future -> emerald, none -> muted.
 */
export const getFollowUpTone = (value) => {
  const date = parseApiDate(value);
  if (!date) return { ...TONES.muted, label: "Not scheduled" };

  const startOfDay = (d) =>
    new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();

  const now = new Date();
  const today = startOfDay(now);
  const target = startOfDay(date);
  const dayDiff = Math.round((target - today) / 86400000);

  if (dayDiff < 0) {
    const days = Math.abs(dayDiff);
    return {
      ...TONES.rose,
      label: days === 1 ? "Overdue by 1 day" : `Overdue by ${days} days`,
    };
  }

  if (dayDiff === 0) {
    return { ...TONES.amber, label: `Today at ${formatTime(value)}` };
  }

  if (dayDiff === 1) {
    return { ...TONES.emerald, label: `Tomorrow at ${formatTime(value)}` };
  }

  return { ...TONES.emerald, label: `In ${dayDiff} days — ${formatDate(value)}` };
};

