/* ------------------------------------------------------------------ *
 * Activity row icons (spec 7.5)
 * ------------------------------------------------------------------ */

export const getActivityIcon = (type) => {
  const map = {
    Post: { icon: "MessageSquare", className: "text-indigo-600" },
    Update: { icon: "RefreshCcw", className: "text-blue-600" },
    Assign: { icon: "UserPlus", className: "text-purple-600" },
    Create: { icon: "PlusCircle", className: "text-green-600" },
  };
  return map[type] || { icon: "Activity", className: "text-gray-500" };
};

/* ------------------------------------------------------------------ *
 * Shared date formatting
 * ------------------------------------------------------------------ */

/**
 * EspoCRM datetimes ("YYYY-MM-DD HH:mm:ss") are UTC; append Z so JS
 * converts them to the user's local timezone for display.
 */
export const parseApiDate = (value) => {
  if (!value) return null;
  const safe =
    typeof value === "string" && value.length > 10
      ? `${value.replace(" ", "T")}${value.endsWith("Z") ? "" : "Z"}`
      : value;
  const parsed = new Date(safe);
  return Number.isNaN(parsed.getTime()) ? null : parsed;
};

/** `MMM d, yyyy` (e.g. Mar 4, 2026). Null/invalid renders an em dash. */
export const formatDate = (value) => {
  const date = parseApiDate(value);
  if (!date) return "—";
  return new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  }).format(date);
};

/** `h:mm a` (e.g. 10:00 AM). */
export const formatTime = (value) => {
  const date = parseApiDate(value);
  if (!date) return "—";
  return new Intl.DateTimeFormat("en-US", {
    hour: "numeric",
    minute: "2-digit",
    hour12: true,
  }).format(date);
};

/** True when the API value carries a meaningful time component. */
export const hasTime = (value) =>
  typeof value === "string" && value.length > 10 && !value.endsWith("00:00:00");

/**
 * Convert a Date into the `YYYY-MM-DDTHH:mm` string a datetime-local
 * input expects, in local time.
 */
export const toDatetimeLocal = (date) => {
  if (!date) return "";
  const pad = (n) => String(n).padStart(2, "0");
  return (
    `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}` +
    `T${pad(date.getHours())}:${pad(date.getMinutes())}`
  );
};

