export const LEAD_STATUS_OPTIONS = LEAD_STATUS_VALUES.map((value) => ({
  value,
  label: getStatusLabel(value),
}));

/**
 * Filter values. Adds QDTD: a lead can CARRY "Qualify Due To Delay" (the
 * backend writes it) but no drawer offers it as a settable status, so it
 * is filterable only.
 *
 * No "All" entry, unlike web: the mobile Status select treats an empty
 * value as "no filter" and shows its placeholder, so an explicit "All
 * Leads" row would be a second way to say the same thing.
 */
export const LEAD_FILTER_STATUS_OPTIONS = [
  { value: "QDTD", label: getStatusLabel("QDTD") },
  ...LEAD_STATUS_OPTIONS,
];
